---
/**
 * @title TableOfContents
 * @level liftoff
 * @description Themed table-of-contents navigation built from consumer-supplied anchor links.
 * @category Content
 * @hydration none
 * @accessibility
 * - Renders a labelled `<nav>`; links must use real `href` values.
 * @keyboard
 * - Native anchor keyboard behavior.
 * @slots
 * - `default`: Nested `<ul>` / `<li>` / `<a>` outline.
 */

import "./content.css";

type Props = {
  class?: string;
  id?: string;
  label?: string;
};

---

<nav data-lsui-toc aria-label={Astro.props.label ?? "On this page"} {...Astro.props}>
  <slot />
</nav>

/* LightSpeedUI Level 2 — content and publishing styles; semantic tokens only. */
@layer lsui {
  @layer components {
    [data-lsui-prose],
    [data-lsui-portable-text],
    [data-lsui-blocks] {
      color: var(--color-text);
      font-family: var(--font-body);
      line-height: var(--leading-relaxed);
    }

    [data-lsui-prose] :is(h1, h2, h3, h4) {
      line-height: var(--leading-tight);
      margin-block-start: var(--space-lg);
    }

    [data-lsui-byline],
    [data-lsui-post-meta] {
      display: flex;
      flex-wrap: wrap;
      gap: var(--space-2);
      color: var(--color-text-muted);
      font-size: var(--text-sm);
    }

    [data-lsui-post-card] {
      display: grid;
      gap: var(--space-2);
      padding: var(--space-md);
      border: var(--border-width) solid var(--color-border);
      border-radius: var(--radius-md);
      background: var(--color-surface);
      color: var(--color-text);
    }

    [data-lsui-post-card] a {
      color: var(--color-text);
      text-decoration-thickness: var(--border-width);
      text-underline-offset: var(--space-1);
    }

    [data-lsui-toc] nav ul {
      list-style: none;
      padding-inline-start: 0;
    }

    [data-lsui-pagination] {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: var(--space-md);
      padding-block: var(--space-lg);
    }

    [data-lsui-pagination] a {
      min-block-size: var(--target-min-size, 1.5rem);
      color: var(--color-text);
    }
  }
}
